const payload = $json.body ?? $json;
const event = payload.bot_event ?? payload.event;
if (event !== 'transcription.processed' || payload.transcript_status !== 'Success') return [];
if (!payload.bot_id) throw new Error('MeetStream webhook did not include bot_id.');
return [{ json: { ...payload, bot_id: String(payload.bot_id) } }];

const runs = Array.isArray($json.transcriptions) ? $json.transcriptions : Array.isArray($json.data) ? $json.data : [];
const createdAt = (run) => { const time = Date.parse(run.created_at ?? ""); return Number.isFinite(time) ? time : -Infinity; };
const completed = runs.filter((run) => run?.status === 'Success' && run.transcript_id).sort((a, b) => createdAt(b) - createdAt(a));
if (!completed.length) throw new Error('No successful post-call transcription run was returned.');
return [{ json: { transcript_id: completed[0].transcript_id } }];

const segments = (Array.isArray($json.data) ? $json.data : []).map((segment) => {
  const transcript = typeof segment?.transcript === 'string' && segment.transcript.trim()
    ? segment.transcript
    : Array.isArray(segment?.words) ? segment.words.filter((word) => typeof word?.text === 'string' && word.text.trim()).map((word) => word.text.trim()).join(' ') : '';
  const speaker = segment?.speaker ?? segment?.participant?.name;
  return { transcript, speaker: typeof speaker === 'string' && speaker.trim() ? speaker : 'Speaker' };
}).filter((segment) => segment.transcript.trim());
if (!segments.length) throw new Error('MeetStream returned an empty transcript.');
const full = segments.map((segment) => `${segment.speaker ?? 'Speaker'}: ${segment.transcript ?? ''}`).join('\n');
return [{ json: { bot_id: $('Accept successful transcript event').item.json.bot_id, transcript: full.slice(0, 60000) } }];

const text = ($json.output ?? []).filter((message) => message?.type === 'message').flatMap((message) => message.content ?? []).filter((part) => part?.type === 'output_text' && typeof part.text === 'string').map((part) => part.text).join('\n');
const raw = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch { throw new Error('OpenAI did not return valid action-item JSON.'); }
if (!Array.isArray(parsed?.items)) throw new Error('OpenAI response is missing the items array.');
const botId = $('Accept successful transcript event').item.json.bot_id;
const normalize = (value) => String(value ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
const transcript = normalize($('Prepare transcript').item.json.transcript);
const candidates = parsed.items.filter((item) => typeof item?.task === 'string' && item.task.trim());
for (const item of candidates) {
  const quote = normalize(item.evidence);
  if (!quote || !transcript.includes(quote)) throw new Error('AI output needs a matching transcript quote before writing to a destination. Review the generated evidence and retry.');
  for (const field of ['owner', 'due_date']) {
    if (normalize(item[field]) && !quote.includes(normalize(item[field]))) item[field] = '';
  }
}
const seen = new Set();
return candidates
  .filter((item) => normalize(item.evidence).includes(normalize(item.task)))
  .filter((item) => { const key = [item.task, item.owner, item.due_date].map(normalize).join("|"); if (seen.has(key)) return false; seen.add(key); return true; })
  .map((item) => ({ json: {
    task: item.task.trim().slice(0, 500),
    owner: String(item.owner ?? '').trim(),
    due_date: String(item.due_date ?? '').trim(),
    evidence: String(item.evidence ?? '').trim(),
    bot_id: botId
  } }));

